import java.util.function.IntSupplier;
class Example {
    static class Client {
        final IntSupplier read;
        Client(IntSupplier read) { this.read = read; }
        int execute() { return read.getAsInt() * 2; }
    }
    static int demo() { return new Client(() -> 5).execute() + new Client(() -> 7).execute(); }
}

class Client:
    def __init__(self, read):
        self.read = read
    def execute(self):
        return self.read() * 2

def demo():
    return Client(lambda: 5).execute() + Client(lambda: 7).execute()

import java.util.function.IntSupplier;
class Example {
    static class Locator {
        IntSupplier resolve(int key) { return key == 1 ? () -> 42 : () -> 0; }
    }
    static int client(Locator locator) { return locator.resolve(1).getAsInt(); }
    static int demo() { return client(new Locator()); }
}

class Locator:
    def resolve(self, key):
        return (lambda: 42) if key == 1 else (lambda: 0)

def client(locator):
    return locator.resolve(1)()

def demo():
    return client(Locator())

import java.util.function.IntConsumer;
class Example {
    static final IntConsumer SILENT = value -> {};
    static int execute(int value, IntConsumer log) {
        log.accept(value);
        return value;
    }
    static int demo() { return execute(10, SILENT); }
}

def silent(value):
    pass

def execute(value, log=silent):
    log(value)
    return value

def demo():
    return execute(10)

class Example {
    static class Resource { final int id = 7; }
    static class Pool {
        Resource free = new Resource();
        Resource take() { Resource result = free; free = null; return result; }
        void give(Resource item) { free = item; }
    }
    static int demo() {
        Pool pool = new Pool(); Resource first = pool.take();
        Resource busy = pool.take(); pool.give(first);
        Resource again = pool.take();
        return first == again && busy == null ? 1 : 0;
    }
}

class Resource:
    id = 7

class Pool:
    def __init__(self):
        self.free = Resource()
    def take(self):
        result, self.free = self.free, None
        return result
    def give(self, item):
        self.free = item

def demo():
    pool = Pool()
    first, busy = pool.take(), pool.take()
    pool.give(first)
    again = pool.take()
    return int(first is again and busy is None)

class Example {
