    static int demo() { return create(0).cost() + create(1).cost(); }
}

class Product:
    def __init__(self, cost):
        self.cost = cost

def create(kind):
    return Product(5 if kind == 0 else 9)

def demo():
    return create(0).cost + create(1).cost

class Example {
    static class Settings { int value; }
    static class Registry {
        final Settings first = new Settings(), second = new Settings();
        Settings get(int key) { return key == 0 ? first : second; }
    }
    static int demo() {
        Registry r = new Registry();
        Settings a = r.get(0), b = r.get(0), c = r.get(1);
        a.value = 7;
        return b.value * 10 + c.value;
    }
}

class Settings:
    def __init__(self):
        self.value = 0

class Registry:
    def __init__(self):
        self.first, self.second = Settings(), Settings()
    def get(self, key):
        return self.first if key == 0 else self.second

def demo():
    registry = Registry()
    a, b, c = registry.get(0), registry.get(0), registry.get(1)
    a.value = 7
    return b.value * 10 + c.value

class Example {
    interface Auditable {}
    static class Marked implements Auditable {}
    static class Unmarked { int value = 7; }
    static int accepts(Object item) { return item instanceof Auditable ? 1 : 0; }
    static int demo() { return accepts(new Marked()) * 10 + accepts(new Unmarked()); }
}

class Auditable:
    pass

class Marked(Auditable):
    pass

class Unmarked:
    value = 7

def accepts(item):
    return int(isinstance(item, Auditable))

def demo():
    return accepts(Marked()) * 10 + accepts(Unmarked())

class Example {
    static class Options {
        int count, price;
        Options withCount(int value) { count = value; return this; }
        Options withPrice(int value) { price = value; return this; }
        int total() { return count * price; }
