class Example {
    static class TypeData { int damage = 2; }
    record Item(TypeData kind) {}
    static int damage(Item item) { return item.kind().damage; }
    static int demo() {
        TypeData kind = new TypeData();
        Item first = new Item(kind), second = new Item(kind);
        int before = damage(first); kind.damage = 3;
        return before * 10 + damage(second);
    }
}

class TypeData:
    def __init__(self, damage):
        self.damage = damage

class Item:
    def __init__(self, kind):
        self.kind = kind

def damage(item):
    return item.kind.damage

def demo():
    kind = TypeData(2)
    first, second = Item(kind), Item(kind)
    before = damage(first)
    kind.damage = 3
    return before * 10 + damage(second)

class Example {
    static class Host {
        int value = 7; Report extension;
        void install(Report addon) { extension = addon; }
        Report query() { return extension; }
    }
    record Report(Host target) { int render() { return target.value * 2; } }
    static int demo() {
        Host host = new Host(); host.install(new Report(host));
        return host.query().render();
    }
}

class Host:
    def __init__(self):
        self.value, self.extension = 7, None
    def install(self, addon):
        self.extension = addon
    def query(self):
        return self.extension

class Report:
    def __init__(self, target):
        self.target = target
    def render(self):
        return self.target.value * 2

def demo():
    host = Host()
    host.install(Report(host))
    return host.query().render()
